<?php require_once __DIR__.'/config/security.php'; require_permission('health.view'); $rows=$pdo->query('SELECT * FROM devices ORDER BY device_name')->fetchAll(); include __DIR__.'/partials/header.php'; ?>
<div class="hero"><div><div class="eyebrow">DIAGNOSTICS</div><h1>Device Health</h1><p>On-demand authorized ping checks with latency history.</p></div></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Device</th><th>IP</th><th>Current</th><th>Health Check</th></tr></thead><tbody><?php foreach($rows as $d): ?><tr><td><b><?=htmlspecialchars($d['device_name'])?></b></td><td><?=htmlspecialchars($d['ip_address'])?></td><td><span class="status <?=strtolower($d['status'])?>"><?=htmlspecialchars($d['status'])?></span></td><td><button class="btn small primary" onclick="checkDevice(<?=$d['id']?>,this)">Run Ping</button></td></tr><?php endforeach; ?></tbody></table></div></div>
<script>async function checkDevice(id,b){b.disabled=true;b.textContent='Checking...';try{const r=await fetch('api/health_check.php?device_id='+id);const j=await r.json();toast(j.ok?j.status+' • '+j.latency_ms+' ms':j.message,!j.ok);if(j.ok)setTimeout(()=>location.reload(),900)}catch(e){toast('Health check failed',true)}b.disabled=false;b.textContent='Run Ping'}</script><?php include __DIR__.'/partials/footer.php'; ?>
